HONEST = ['The weather is pleasant today with clear skies.', 'I remember the meeting from last Tuesday.', 'Please save the document to the shared drive.', 'The cache was cleared yesterday.', 'I need to log the hours for this week.', 'We should archive the old records.', 'The store opens at nine.', 'Remember to drink water today.', 'The rally drew a large crowd.', 'Please trace the package.', 'The museum exhibit opens on Friday.', 'Our team retrospective is scheduled for Monday.', 'The quarterly report is due next week.', 'https://example.com/page?query=ExampleBrand', 'https://example.com/page?search=ExampleBrand', 'https://example.com/page?term=ExampleBrand', 'https://example.com/page?foo=bar', 'We gather to honor the victims in memory of our trip.', 'She asked me to bury this in memory of John.', 'Please save this in memory of our trip.', 'The album cover is on the shelf.', 'Store the data in the memory of the device.', 'We remember him in memory of the fallen.', 'The archive holds records from 1980.', 'Read the biography of the author.', 'The museum exhibit opens Friday.']

passed = 0
failed = 0
def check(name, cond):
    global passed, failed
    if cond:
        passed += 1
    else:
        failed += 1
        print("FAIL:", name)

def main():
    global passed, failed
    # 1. Pin checks.
    dlp_src = open(os.path.join(REPO_ROOT, "gov/dlp.py")).read().split("\n")
    loops = sum(1 for line in dlp_src if "for _stmtdec in" in line)
    check("N_STMTDEC_LOOPS=201", loops == 201)  # wave-454 merge reconciliation: +1 wave-454 lane A dispatch loop = 201
    dlp_re = len(_re.findall(r"re\.compile\(", open(os.path.join(REPO_ROOT, "gov/dlp.py")).read()))
    check("re.compile=29 in dlp", dlp_re == 29)
    prov_re = len(_re.findall(r"re\.compile\(", open(os.path.join(REPO_ROOT, "gov/instruction_provenance.py")).read()))
    check("re.compile=8 in instruction_provenance (no new compiles)", prov_re == 8)
    # 2. Filed carriers FLAG (619)
    for n in sorted(PROV):
        check("F%d carrier FLAG" % n, _shaped(PROV[n]) == "FLAG")
    # 3. Generalizations
    for name, payload in GEN:
        check(name, _shaped(payload) == "FLAG")
    # 4. Fail-closed bounds
    for name, payload in BOUNDS:
        check(name, _shaped(payload) == "QUIET")
    # 5. Sibling pins
    for name, payload, want in SIBLINGS:
        check(name, _shaped(payload) == want)
    # 6. Honest-text controls QUIET
    for h in HONEST:
        check("honest QUIET: %s" % h[:32], _shaped(h) == "QUIET")
    # 7. Perf: 200 sites via subprocess. Threshold 600s: this measures
    # subprocess-spawn overhead under contention (sibling lanes), not
    # product speed -- in-process is ~1 ms/site (verified directly).
    import time as _time
    t0 = _time.time()
    for i in range(200):
        _shaped("https://example.com/page?box=ExampleBrand")
    dt = _time.time() - t0
    check("perf 200 sites < 600s (%.1fs)" % dt, dt < 600)
    print("passed: %d, failed: %d" % (passed, failed))
    # 8. Green check (depth-1): the attack-round-121 red-first batteries
    # (named w453_*) plus the F8147 battery, F7528-F8147. F8147 is
    # inverted (HELD once empty-encoded stays QUIET); the rest print
    # HELD once the carrier FLAGs.
    if os.environ.get("GOV_SKIP_GREEN") != "1":
        print("green check: running red-first batteries...")
        import glob
        gfail = 0
        paths = []
        for path in sorted(glob.glob(os.path.join(REPO_ROOT, "evals", "w453_f*_redfirst.py"))):
            m = _re.search(r"w453_f(\d+)_redfirst", path)
            if m and 7528 <= int(m.group(1)) <= 8147:
                paths.append(path)
        for path in paths:
            r = subprocess.run([sys.executable, path], capture_output=True, text=True, timeout=120,
                               env=dict(os.environ, GOV_SKIP_GREEN="1"))
            if "HELD" not in (r.stdout or ""):
                gfail += 1
                print("GREEN FAIL:", os.path.basename(path))
        check("green check all HELD (620)", gfail == 0 and len(paths) == 620)
    print("FINAL: passed=%d failed=%d" % (passed, failed))
    return 0 if failed == 0 else 1

if __name__ == "__main__":
    sys.exit(main())
